       IF crosshair       MACRO XORN        LD A,(HL)        XOR \0        LD (HL),A       ENDM CROSSHAIR        LD HL,scrbuf+(scrwid/2<8)+(scrhgtpix/2)        XORN #0F        DEC H        XORN #78        INC L        XORN #78        INC H        XORN #0F        LD L,scrbuf+(scrhgtpix/2)-7        XORN #80        LD L,scrbuf+(scrhgtpix/2)-3        XORN #80        LD L,scrbuf+(scrhgtpix/2)+4        XORN #80        LD L,scrbuf+(scrhgtpix/2)+8        XORN #80        RET        ENDIF ;crosshairCHECKHEIGHTS        LD HL,distbuf+#200 ;dist        LD DE,scrbufflag        LD BC,scrwid<8+lowmaxscalecheckheights0        LD A,C;lowmaxscale_=pixperchr       DUP pixperchr_=_-1        CP (HL)       IF debug       CALL npp       ENDIF         INC L        jr C,checkhigh-_       EDUP         XOR A        JP checklow       DUP pixperchr        INC L       EDUP checkhigh ;A<>0 <128checklow ;A=0        LD (DE),A        INC D        DJNZ checkheights0        RET        IF debugnpp       PUSH AF       PUSH HL        jr C,NNN        LD HL,nlow        INC (HL)        INC HL        jr Z,$-2NNN        LD HL,nstolb        INC (HL)        INC HL        jr Z,$-2       POP HL       POP AF        RET nlow        DS 4nstolb        DS 4       ENDIF CLSCRBUF        LD H,scrbuf/256        LD BC,scrwid*256+(0xff&scrbufflag)        XOR A        LD D,A        ld E,Aclscrbuf0 ;        LD L,C;scrbufflag        CP (HL)        jr NZ,clscrhigh        LD L,0xff&(lowscrbuf+lowscrhgtpix)        LD SP,HL       IF (0xff&(scrbuf+scrhgtpix)) == 0        INC H       ENDIF         JP clscrlowclscrhigh        LD L,0xff&(scrbuf+scrhgtpix)       IF (0xff&(scrbuf+scrhgtpix)) == 0        INC H       ENDIF         LD SP,HL       DUP scrhgtpix/2        PUSH DE       EDUP clscrlow=$-(lowscrhgtpix/2)-1 ;EORFILL could corrupt a word       IF 0xff&(scrbuf+scrhgtpix)        INC H       ENDIF         DJNZ clscrbuf0clscrbuf